hl.bind(mainMod .. " + Return", function()
    hl.exec_cmd(terminal)
end)
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + ALT + E", hl.dsp.exec_cmd("hyprshutdown"))
hl.bind(mainMod .. " + R", function()
    hl.exec_cmd(fileManager)
end)
hl.bind(mainMod .. " + T", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + Space", function()
    hl.exec_cmd(menu)
end)
hl.bind(mainMod .. " + D", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + O", hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + CTRL + L", function()
    hl.exec_cmd("hyprlock")
end)
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.swap({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.swap({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.swap({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.swap({ direction = "down" }))
hl.bind(mainMod .. " + L", hl.dsp.window.move({ x = 10, y = 0 }))
hl.bind(mainMod .. " + H", hl.dsp.window.move({ x = -10, y = 0 }))
hl.bind(mainMod .. " + J", hl.dsp.window.move({ x = 0, y = 10 }))
hl.bind(mainMod .. " + K", hl.dsp.window.move({ x = 0, y = -10 }))
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + Comma", hl.dsp.window.resize({ x = -10, y = 0 }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + Period", hl.dsp.window.resize({ x = 10, y = 0 }), { repeating = true })
hl.bind(mainMod .. " + Period", hl.dsp.window.resize({ x = 0, y = -10 }), { repeating = true })
hl.bind(mainMod .. " + Comma", hl.dsp.window.resize({ x = 0, y = 10 }), { repeating = true })

for i = 1, 10 do
    hl.bind(mainMod .. " + " .. (i % 10), hl.dsp.focus({ workspace = tostring(i % 10) }))
end

hl.bind(mainMod .. " + P", function()
    hl.exec_cmd("$HOME/.config/hypr/scripts/prev_workspace.sh")
end)
hl.bind(mainMod .. " + N", function()
    hl.exec_cmd("$HOME/.config/hypr/scripts/next_workspace.sh")
end)

for i = 1, 10 do
    hl.bind(mainMod .. " + SHIFT + " .. (i % 10), hl.dsp.focus({ workspace = tostring(i % 10) }))
end

hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special({ "magic" }))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.focus({ workspace = "special:magic" }))

hl.bind(mainMod .. " + A", function()
  local is_animated = (hl.get_config("animations.enabled") == true)

  if is_animated then
    hl.config({
      animations = { enabled = false }
    })
  else
    hl.config({
      animations = { enabled = true }
    })
  end
end)

hl.bind(mainMod .. " + G", hl.dsp.submap( "groups" ))

hl.define_submap("groups", function()
    hl.bind(" + U", hl.dsp.group.prev(), { repeating = true })
    hl.bind(" + I", hl.dsp.group.next(), { repeating = true })
    hl.bind(" + H", hl.dsp.focus({ direction = "left" }))
    hl.bind(" + L", hl.dsp.focus({ direction = "right" }))
    hl.bind(" + K", hl.dsp.focus({ direction = "up" }))
    hl.bind(" + J", hl.dsp.focus({ direction = "down" }))
    hl.bind("SHIFT + H", hl.dsp.window.move({ into_or_create_group = "left" }))
    hl.bind("SHIFT + L", hl.dsp.window.move({ into_or_create_group = "right" }))
    hl.bind("SHIFT + K", hl.dsp.window.move({ into_or_create_group = "up" }))
    hl.bind("SHIFT + J", hl.dsp.window.move({ into_or_create_group = "down" }))
    hl.bind(" + T", hl.dsp.group.toggle())
    hl.bind(" + R", hl.dsp.group.lock_active({ toggle }))
    hl.bind(" + E", hl.dsp.window.move( { out_of_group = true }))

    for i = 1, 10 do
        hl.bind(" + " .. (i % 10), hl.dsp.focus({ workspace = tostring(i % 10) }))
    end

    for i = 1, 10 do
        hl.bind("SHIFT + " .. (i % 10), hl.dsp.focus({ workspace = tostring(i % 10) }))
    end

    hl.bind(" + Return", function()
        hl.exec_cmd(terminal)
    end)

    hl.bind(" + G", hl.dsp.submap("reset"))
end)

hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })
hl.bind(" + XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind(" + XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind(" + XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind(" + XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

hl.on("hyprland.start", function()
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("/home/trevor/.local/bin/wp-load")
    hl.exec_cmd("waybar")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
end)

